// Compile-time interface assertion
var _ agent.HookSupport = (*PiAgent)(nil)

//go:embed entire_extension.ts
var extensionTemplate string

const (
	// extensionDirName is the directory pi auto-discovers project-local
	// extensions from.
	extensionDirName = ".pi/extensions/entire"

	// extensionFileName is the file pi loads from extensionDirName.
	extensionFileName = "index.ts"

	// entireMarker identifies the file as Entire-owned. Substring of the
	// auto-generated header so AreHooksInstalled can verify ownership by
	// content (and so it survives the ENTIRE_CMD placeholder substitution).
	entireMarker = "Auto-generated by `entire enable --agent pi`"

	// entireCmdPlaceholder is replaced at install time with either `entire`
	// (production) or a `go run …` path (local-dev).
	entireCmdPlaceholder = "__ENTIRE_CMD__"
)

func extensionPath(ctx context.Context) (string, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		// Fall back to CWD for tests run outside a git repo.
		//nolint:forbidigo // explicit fallback when WorktreeRoot fails
		root, err = os.Getwd()
		if err != nil {
			return "", fmt.Errorf("resolve repo root: %w", err)
		}
	}
	return filepath.Join(root, extensionDirName, extensionFileName), nil
}

func renderExtension(localDev bool) string {
	var cmd string
	if localDev {
		cmd = agent.LocalDevHookScript
	} else {
		cmd = "entire"
	}
	return strings.ReplaceAll(extensionTemplate, entireCmdPlaceholder, cmd)
}

// InstallHooks writes the Entire pi extension to .pi/extensions/entire/index.ts.
// Returns 1 if the extension was written, 0 if already up-to-date (idempotent).
// If the file exists but content differs (e.g., localDev vs production), it is
// rewritten as long as it is recognisable as Entire-owned (contains the
// marker). A foreign file at the same path is left untouched unless force is
// true — this protects user-authored extensions that happen to live at
// .pi/extensions/entire/index.ts.
func (a *PiAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
	path, err := extensionPath(ctx)
	if err != nil {
		return 0, err
	}
	content := renderExtension(localDev)

	if !force {
		//nolint:gosec // path constructed from validated repo root
		existing, readErr := os.ReadFile(path)
		switch {
		case readErr == nil && string(existing) == content:
			return 0, nil // already up-to-date
		case readErr == nil && !strings.Contains(string(existing), entireMarker):
			return 0, fmt.Errorf("refusing to overwrite foreign file at %s; remove it or pass --force", path)
		}
	}

	//nolint:gosec // G301: pi reads the directory; standard 0755 permissions
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return 0, fmt.Errorf("create extension dir: %w", err)
	}
	//nolint:gosec // G306: pi reads the file; standard 0644 permissions
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		return 0, fmt.Errorf("write extension: %w", err)
	}
	return 1, nil
}

// UninstallHooks removes the entire pi extension directory (if present).
func (a *PiAgent) UninstallHooks(ctx context.Context) error {
	path, err := extensionPath(ctx)
	if err != nil {
		return err
	}
	dir := filepath.Dir(path)
	if err := os.RemoveAll(dir); err != nil {
		return fmt.Errorf("remove pi extension dir: %w", err)
	}
	return nil
}

// AreHooksInstalled returns true when the extension file exists and is
// recognisable as Entire-owned (contains the marker string).
func (a *PiAgent) AreHooksInstalled(ctx context.Context) bool {
	path, err := extensionPath(ctx)
	if err != nil {
		return false
	}
	//nolint:gosec // path from validated repo root
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	return strings.Contains(string(data), entireMarker)
}

// Entire CLI extension for Pi
// Auto-generated by `entire enable --agent pi`
// Do not edit manually — changes will be overwritten on next install.
//
// Forwards Pi lifecycle events to `entire hooks pi <event>` so Entire can
// create checkpoints, capture transcripts, and offer rewind/resume.
//
// ENTIRE_CMD is replaced at install time by Entire's installer.

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFile } from "node:child_process";

export default function (pi: ExtensionAPI) {
  const ENTIRE_CMD = "__ENTIRE_CMD__";
  let pendingSkillEvents: Array<{ skill_name: string; invocation: string; timestamp: string }> = [];

  // fireHook pipes data to `entire hooks pi <hookName>` and resolves with the
  // hook's stdout (empty string on any failure). Most hooks ignore the return;
  // before_agent_start uses it to apply a model-context injection.
  function fireHook(hookName: string, data: Record<string, unknown>): Promise<string> {
    return new Promise((resolve) => {
      try {
        const child = execFile(
          "sh",
          ["-c", `${ENTIRE_CMD} hooks pi ${hookName}`],
          { timeout: 10000, windowsHide: true, maxBuffer: 4 * 1024 * 1024 },
          (_err, stdout) => resolve(typeof stdout === "string" ? stdout : ""),
        );
        child.stdin?.end(JSON.stringify(data));
      } catch {
        // best effort — never block the agent on a hook failure
        resolve("");
      }
    });
  }

  // parseInjectedContext scans a hook's stdout for Entire's injection envelope
  // ({"inject_context":"..."}) and returns the text to inject, or null.
  function parseInjectedContext(stdout: string): string | null {
    if (!stdout) return null;
    for (const line of stdout.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed.startsWith("{")) continue;
      try {
        const parsed = JSON.parse(trimmed) as { inject_context?: unknown };
        if (typeof parsed.inject_context === "string" && parsed.inject_context.length > 0) {
          return parsed.inject_context;
        }
      } catch {
        // not our envelope — ignore
      }
    }
    return null;
  }

  function parseSkillInvocation(text: string): { skill_name: string; invocation: string } | null {
    const match = text.trimStart().match(/^\/skill:([a-z0-9][a-z0-9-]{0,63})(?:\s|$)/);
    if (!match) return null;
    const invocation = text.trimStart().split(/\s+/, 1)[0] ?? `/skill:${match[1]}`;
    return { skill_name: match[1], invocation };
  }

  pi.on("input", async (event) => {
    const skill = parseSkillInvocation(event.text);
    if (skill) {
      pendingSkillEvents.push({ ...skill, timestamp: new Date().toISOString() });
    }
    return { action: "continue" };
  });

  // Agent-driven bash subprocesses inherit a real TTY but cannot answer
  // hook prompts. Disable git/Entire terminal prompts for bash calls so
  // Entire treats agent-driven commits as non-interactive.
  pi.on("tool_call", async (event) => {
    if (event.toolName !== "bash") return;
    const input = event.input as { command?: string };
    if (typeof input.command !== "string" || input.command.includes("GIT_TERMINAL_PROMPT=")) {
      return;
    }
    input.command = "export GIT_TERMINAL_PROMPT=0\n" + input.command;
  });

  pi.on("session_start", async (_event, ctx) => {
    await fireHook("session_start", {
      type: "session_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("before_agent_start", async (event, ctx) => {
    const skillEvents = pendingSkillEvents;
    pendingSkillEvents = [];
    const stdout = await fireHook("before_agent_start", {
      type: "before_agent_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
      prompt: event.prompt,
      skill_events: skillEvents,
    });
    const injected = parseInjectedContext(stdout);
    if (injected) {
      // Inject a hidden, persistent message so the model learns about Entire.
      // display:false keeps it out of the user-facing transcript while still
      // sending it to the LLM. Entire emits this at most once per session.
      return {
        message: {
          customType: "entire-context",
          content: injected,
          display: false,
        },
      };
    }
  });

  pi.on("agent_end", async (_event, ctx) => {
    await fireHook("agent_end", {
      type: "agent_end",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("session_shutdown", async () => {
    await fireHook("session_shutdown", { type: "session_shutdown" });
  });
}

		)
	}
	return nil
}

// normalizeToolUsePaths converts hook-payload paths to repo-root-relative form.
// Codex apply_patch envelopes carry cwd-relative paths, so we join them against
// eventCWD before FilterAndNormalizePaths rewrites against repoRoot.
func normalizeToolUsePaths(files []string, eventCWD, repoRoot string) []string {
	if len(files) == 0 {
		return nil
	}
	resolved := make([]string, 0, len(files))
	for _, f := range files {
		if f == "" {
			continue
		}
		if filepath.IsAbs(f) || eventCWD == "" {
			resolved = append(resolved, f)
			continue
		}
		resolved = append(resolved, filepath.Join(eventCWD, f))
	}
	return FilterAndNormalizePaths(resolved, repoRoot)
}

// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
// ensures strategy setup, initializes session.
// entireTrailContextInjection is the one-time, model-facing documentation Entire
// injects to teach the agent the `entire trail` command. Kept terse: it costs
// context-window tokens on the first turn of every session, and states no
// transient fact (whether a trail exists can change at any time).
func entireTrailContextInjection() string {
	return "A trail ties together the context for a branch. Use `entire trail` to view, create, update, or watch it."
}

// emitContextInjection writes ag's native context-injection payload to stdout
// when ag injects at event.Type, trails are enabled for the repo on the API,
// and this session has not been injected yet. Best-effort: an injection failure
// never fails the hook.
func emitContextInjection(ctx context.Context, ag agent.Agent, event *agent.Event) {
	injector, ok := agent.AsContextInjector(ag)
	if !ok || injector.InjectionEvent() != event.Type || event.SessionID == "" {
		return
	}
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())

	// Decide once per session, recorded on the session state itself (not a
	// separate marker file). Winning the check-and-set means this turn owns the
	// decision. trailsEnabledForRepo only reads clone-local cached enablement;
	// the API refresh happens earlier on `entire enable`, outside the prompt path.
	// Marking "decided" before checking the cache means a missing/stale false
	// cache fails closed (no hint for this session) rather than retrying/spamming.
	mutated := false
	mutErr := strategy.MutateSessionState(ctx, event.SessionID, func(state *strategy.SessionState) error {
		if state.ContextInjectionDecided {
			return strategy.ErrMutationSkip
		}
		// Review/investigate sessions are task-specific and don't need the branch
		// trail pointer; skip without marking decided so normal sessions keep the
		// usual first-turn behavior.
		if state.Kind != "" {
			return strategy.ErrMutationSkip
		}
		state.ContextInjectionDecided = true
		mutated = true
		return nil
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logCtx, "failed to record context injection decision",
			slog.String("error", mutErr.Error()))
		return
	}
	// Only proceed after the state mutation was persisted. If saving the updated
	// state failed, mutErr was non-nil above and we returned without injecting,
	// leaving a later turn free to retry safely.
	won := mutErr == nil && mutated
	if !won {
		return // already decided for this session, skipped kind, or no session state yet
	}

	// Only advertise trails when they're literally enabled for this repo on the API.
	if !trailsEnabledForRepo(ctx) {
		return
	}

	payload, err := injector.RenderContextInjection(agent.ContextInjection{Text: entireTrailContextInjection()})
	if err != nil {
		logging.Warn(logCtx, "failed to render context injection",
			slog.String("error", err.Error()))
		return
	}
	if len(payload) == 0 {
		return
	}
	if _, err := os.Stdout.Write(payload); err != nil {
		logging.Warn(logCtx, "failed to write context injection",
			slog.String("error", err.Error()))
	}
}

func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "turn-start",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
		slog.String("model", event.Model),
	)

	sessionID := event.SessionID
	if sessionID == "" {
		return fmt.Errorf("no session_id in %s event", event.Type)
	}
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid %s event: %w", event.Type, err)
	}

	// Fill model from hint file if the agent didn't provide it on this hook
	if event.Model == "" {
		if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
			event.Model = hint
			logging.Debug(logCtx, "loaded model from hint file",
				slog.String("model", hint))
		}
	}

	// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
	_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
	if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
		captureSpan.RecordError(err)
		captureSpan.End()
		return err
	}
	captureSpan.End()

	// Append prompt to prompt.txt on filesystem so it's available for
	// mid-turn commits (before SaveStep writes it to the shadow branch).
	// Prompts are separated by "\n\n---\n\n" to support multiple turns.
	if event.Prompt != "" {
		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
		if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
			if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
				promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
				existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
				var content string
				if readErr == nil && len(existing) > 0 {
					content = string(existing) + "\n\n---\n\n" + event.Prompt
				} else {
					content = event.Prompt
				}
				if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
					logging.Warn(logCtx, "failed to write prompt.txt",
						slog.String("error", writeErr.Error()))
				}
			}
		}
	}

	// Ensure strategy setup and initialize session
	_, initSpan := perf.Start(ctx, "init_session")
	if err := strategy.EnsureSetup(ctx); err != nil {
		logging.Warn(logCtx, "failed to ensure strategy setup",
			slog.String("error", err.Error()))
	}

	strat := GetStrategy(ctx)
	if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
		logging.Warn(logCtx, "failed to initialize session state",
			slog.String("error", err.Error()))
	}

	// Best-effort: adopt ENTIRE_REVIEW_* / ENTIRE_INVESTIGATE_* env vars set
	// by `entire review` / `entire investigate` on the spawned agent process.
	// Each agent process has its own env, so there is no file race across
	// worktrees. Errors in load/save must not fail the turn.
	//
	// Review adoption runs first; if both env families are somehow set, review
	// wins. Production strips ENTIRE_REVIEW_* in AppendInvestigateEnv before
	// spawning each per-turn investigate agent process so this conflict cannot
	// happen for fresh investigate spawns. Both functions short-circuit on
	// state.Kind != "" to keep the conflict harmless if it ever arises.
	if mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
		before := *state
		// Slice fields share their backing array under struct copy. If
		// adoptReviewEnv ever mutates ReviewSkills in place, the diff check
		// below would silently miss it. Clone to keep the comparison honest.
		before.ReviewSkills = slices.Clone(state.ReviewSkills)
		adoptReviewEnv(logCtx, state, string(ag.Name()))
		adoptInvestigateEnv(logCtx, state, string(ag.Name()))

		skillEventSource := *event
		// Record a skill event for a leading "/<command>" in the raw prompt. Only
		// once ownership is known — TurnStart bypasses the owner filter so
		// InitializeSession can repair it — and never overriding native adapter events.
		if state.AgentType == "" || state.AgentType == ag.Type() {
			skillEventSource.SkillEvents = agent.AppendPromptSlashCommandSkillEvent(
				skillEventSource.SkillEvents,
				string(ag.Name()),
				event.Prompt,
				event.Timestamp,
			)
		}
		skillEventsChanged := appendEventSkillEventsToState(&skillEventSource, state)
		if state.Kind == before.Kind &&
			state.ReviewPrompt == before.ReviewPrompt &&
			slices.Equal(state.ReviewSkills, before.ReviewSkills) &&
			state.InvestigateRunID == before.InvestigateRunID &&
			state.InvestigateTopic == before.InvestigateTopic &&
			!skillEventsChanged {
			return strategy.ErrMutationSkip
		}
		return nil
	}); mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logCtx, "failed to save session state after review/investigate env adoption",
			slog.String("error", mutErr.Error()))
	}
	initSpan.End()

	// Inject Entire's model-facing context (once per session) for agents whose
	// transport supports it at TurnStart (e.g. Pi). Extension reads stdout.
	emitContextInjection(ctx, ag, event)

	return nil
}

